argv:
$ErrorActionPreference='Stop'
$cfg='E:\WebAIBridge\app\data\supervisor-watchdog.json'
if(!(Test-Path $cfg)){ throw "missing supervisor config" }
$j=Get-Content $cfg -Raw | ConvertFrom-Json
[pscustomobject]@{
  mode=$j.mode
  enabled=$j.enabled
  profileId=$j.profileId
  supervisorChatUrl=$j.supervisorChatUrl
  managedProjects=@($j.managedProjects | ForEach-Object {
    [pscustomobject]@{id=$_.id;name=$_.name;enabled=$_.enabled;profileId=$_.profileId}
  })
  managedChats=@($j.managedChats | ForEach-Object {
    [pscustomobject]@{
      id=$_.id;name=$_.name;url=$_.url;providerConversationId=$_.providerConversationId;
      projectId=$_.projectId;role=$_.role;repository=$_.repository;branch=$_.branch;
      gitHead=$_.gitHead;enabled=$_.enabled;profileId=$_.profileId;
      runtimeTargetTabId=$_.runtimeTargetTabId;runtimeBindingSource=$_.runtimeBindingSource
    }
  })
} | ConvertTo-Json -Depth 6 -Compress
